using OutreachFlow.Domain.Campaigns;
namespace OutreachFlow.Application.Campaigns;
public interface ICampaignRepository { Task AddAsync(Campaign campaign, CancellationToken cancellationToken = default); Task<Campaign?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default); Task<IReadOnlyList<Campaign>> ListAsync(CancellationToken cancellationToken = default); Task<IReadOnlyList<CampaignContact>> ContactsAsync(Guid id, CancellationToken cancellationToken = default); Task<IReadOnlyList<CampaignContactGroup>> GroupsAsync(Guid id, CancellationToken cancellationToken = default); Task<IReadOnlyList<CampaignAttachment>> AttachmentsAsync(Guid id, CancellationToken cancellationToken = default); Task ReplaceAsync(Guid id, IReadOnlyList<CampaignContact> contacts, IReadOnlyList<CampaignContactGroup> groups, IReadOnlyList<CampaignAttachment> attachments, CancellationToken cancellationToken = default); void Remove(Campaign campaign); }
